head.script:
scwin.trigger1_onclick = function(e) {
    var title = "windowContainer_wframeMode_WEFF-505_(WSQ-3874)_sub_auto" + scwin.cnt;
    var xml = "windowContainer_wframeMode_WEFF-505_(WSQ-3874)_sub_auto.xml";
    windowContainer1.createWindow(title, null, xml);
    scwin.cnt++;
};
scwin.checkVal = function() {
    return localStorage.getItem('log') == 'mf_';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'mf_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'mf_windowContainer1_subWindow0_wframe_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.cnt = 1;
    localStorage.removeItem("log");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
